// SaleServiceHandler is an implementation of the pos_iface.v1.SaleService service.
type SaleServiceHandler interface {
	StartSale(context.Context, *connect.Request[v1.StartSaleRequest]) (*connect.Response[v1.StartSaleResponse], error)
	GetSale(context.Context, *connect.Request[v1.GetSaleRequest]) (*connect.Response[v1.GetSaleResponse], error)
	ListSales(context.Context, *connect.Request[v1.ListSalesRequest]) (*connect.Response[v1.ListSalesResponse], error)
	AddItem(context.Context, *connect.Request[v1.AddItemRequest]) (*connect.Response[v1.AddItemResponse], error)
	SetItemQuantity(context.Context, *connect.Request[v1.SetItemQuantityRequest]) (*connect.Response[v1.SetItemQuantityResponse], error)
	RemoveItem(context.Context, *connect.Request[v1.RemoveItemRequest]) (*connect.Response[v1.RemoveItemResponse], error)
	SetSaleCustomer(context.Context, *connect.Request[v1.SetSaleCustomerRequest]) (*connect.Response[v1.SetSaleCustomerResponse], error)
	// FireToKitchen sends the lines added since the last fire to the kitchen
	// printer and stamps them fired. Incremental by design: a dine-in bill grows
	// across rounds, and reprinting the whole order each time would have the
	// kitchen cook the starters twice.
	FireToKitchen(context.Context, *connect.Request[v1.FireToKitchenRequest]) (*connect.Response[v1.FireToKitchenResponse], error)
	// SetItemNote sets the cook-facing note on a cart line ("no ice", "extra
	// pedas"). Never affects any amount — a priced modifier is a different
	// feature. DRAFT only.
	SetItemNote(context.Context, *connect.Request[v1.SetItemNoteRequest]) (*connect.Response[v1.SetItemNoteResponse], error)
	// AttachPrescription / DetachPrescription — pharmacy-mode POS flow. Open to
	// everyone who can run POS (the dispensing happens at the till). The Rx
	// *authoring* authority is separate (PrescriptionService Create/Update/Void).
	AttachPrescription(context.Context, *connect.Request[v1.AttachPrescriptionRequest]) (*connect.Response[v1.AttachPrescriptionResponse], error)
	DetachPrescription(context.Context, *connect.Request[v1.DetachPrescriptionRequest]) (*connect.Response[v1.DetachPrescriptionResponse], error)
	// SetServiceFee overrides the sale's biaya jasa (service fee) at the till. The
	// value defaults from the attached resep on AttachPrescription; this lets the
	// cashier adjust it. DRAFT only.
	SetServiceFee(context.Context, *connect.Request[v1.SetServiceFeeRequest]) (*connect.Response[v1.SetServiceFeeResponse], error)
	// SetLineDiscount sets a per-item discount (FIXED amount or PERCENT) on a cart
	// line and recomputes the line + sale totals. DRAFT only.
	SetLineDiscount(context.Context, *connect.Request[v1.SetLineDiscountRequest]) (*connect.Response[v1.SetLineDiscountResponse], error)
	// ClearLineDiscount removes a manual line discount and reverts the line to the
	// auto-applied product discount (if any). DRAFT only.
	ClearLineDiscount(context.Context, *connect.Request[v1.ClearLineDiscountRequest]) (*connect.Response[v1.ClearLineDiscountResponse], error)
	// SetCartDiscount sets a subtotal-level discount (FIXED amount or PERCENT) on
	// the sale and recomputes the total. DRAFT only.
	SetCartDiscount(context.Context, *connect.Request[v1.SetCartDiscountRequest]) (*connect.Response[v1.SetCartDiscountResponse], error)
	CompleteSale(context.Context, *connect.Request[v1.CompleteSaleRequest]) (*connect.Response[v1.CompleteSaleResponse], error)
	VoidSale(context.Context, *connect.Request[v1.VoidSaleRequest]) (*connect.Response[v1.VoidSaleResponse], error)
	// DiscardSale hard-deletes a DRAFT sale (and its items). Used for abandoned
	// POS carts so they leave no VOIDED trace. Only DRAFT sales are discardable.
	DiscardSale(context.Context, *connect.Request[v1.DiscardSaleRequest]) (*connect.Response[v1.DiscardSaleResponse], error)
	// RefundSale fully refunds a COMPLETED order: flips it to REFUNDED, optionally
	// returns its goods to stock (RETURN movements) and reverses pharmacy Rx
	// dispensing, and records the refunded amount. Manager-tier (money + stock
	// reversal) — OWNER + PHARMACIST only, unlike the DRAFT-only VoidSale.
	RefundSale(context.Context, *connect.Request[v1.RefundSaleRequest]) (*connect.Response[v1.RefundSaleResponse], error)
	GetTodaySnapshot(context.Context, *connect.Request[v1.GetTodaySnapshotRequest]) (*connect.Response[v1.GetTodaySnapshotResponse], error)
	GetSalesSummary(context.Context, *connect.Request[v1.GetSalesSummaryRequest]) (*connect.Response[v1.GetSalesSummaryResponse], error)
	// GetMyPerformance returns the CALLER's own COMPLETED-sales metrics (revenue,
	// sale count, items sold) bucketed over a date range. Always self-scoped from
	// the principal — there is no cashier param — and it carries NO profit/COGS,
	// so it can never leak cost basis or another cashier's data. Cashier-facing.
	GetMyPerformance(context.Context, *connect.Request[v1.GetMyPerformanceRequest]) (*connect.Response[v1.GetMyPerformanceResponse], error)
	PrintReceipt(context.Context, *connect.Request[v1.PrintReceiptRequest]) (*connect.Response[v1.PrintReceiptResponse], error)
}

